// Jarvis Agent Bridge — verify the signature and route the op to your
// AI agent service (FastAPI at AGENT_BASE_URL, default host.docker.internal:8001).
//
// Optional HMAC verification: set N8N_WEBHOOK_SECRET to the same value as the
// Supabase secret, and start n8n with NODE_FUNCTION_ALLOW_BUILTIN=crypto so
// require('crypto') is permitted. If the secret is unset, verification is
// skipped (fine for local-only testing, NOT for a public tunnel).
const item = $input.first().json;
const body = item.body || {};
const headers = item.headers || {};
const secret = $env.N8N_WEBHOOK_SECRET;

if (secret) {
  const crypto = require('crypto');
  const ts = headers['x-jarvis-timestamp'];
  const sig = headers['x-jarvis-signature'];
  const raw = JSON.stringify(body);
  const expected = crypto.createHmac('sha256', secret).update(ts + '.' + raw).digest('hex');
  if (!ts || !sig || sig !== expected) {
    throw new Error('Invalid Jarvis signature');
  }
  // Reject stale requests (older than 5 minutes) to prevent replay.
  if (Math.abs(Date.now() - Number(ts)) > 5 * 60 * 1000) {
    throw new Error('Stale Jarvis request');
  }
}

const base = ($env.AGENT_BASE_URL || 'http://host.docker.internal:8001').replace(/\/$/, '');
const op = body.op;
let method = 'POST';
let url = base;
let payload = {};

switch (op) {
  case 'process':
    url = base + '/process';
    payload = { task: body.task, agent_name: body.agent_name || 'default' };
    break;
  case 'coordinate':
    url = base + '/coordinate';
    payload = { task: body.task, agents: body.agents || [] };
    break;
  case 'create_agent':
    url = base + '/agents';
    payload = { name: body.name, role: body.role, tools: body.tools || [] };
    break;
  case 'list_agents':
    method = 'GET';
    url = base + '/agents';
    break;
  case 'list_tools':
    method = 'GET';
    url = base + '/tools';
    break;
  case 'execute_tool':
    url = base + '/tools/execute';
    payload = { tool: body.tool, params: body.params || {} };
    break;
  default:
    throw new Error('Unknown op: ' + op);
}

return [{ json: { method, url, payload } }];
